// Some portions generated by Claude
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();
const stylesheet = path.resolve(__dirname, '..', '..', '..', 'main/frontend/static/styles/workbench-refresh.css');

function queryPageMarkup() {
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ URLSearchParams, window: { location: { search: '' } }, workbench });
    vm.runInContext(fs.readFileSync(path.join(scripts, 'workbenchViews.js'), 'utf8'), context);
    const templates = [];
    const runtime = { nothing: null, html(strings, ...values) {
        const result = { strings: Array.from(strings), values };
        templates.push(result);
        return result;
    }, render() {} };
    context.workbench.views.pageTemplate({ viewId: 'query', vars: [], rows: [], metadata: {} },
        { basePath: '/workbench', repositoryId: 'native', workbench: {} }, runtime);
    return templates.map(template => template.strings.join('')).join('');
}

/** The rules inside the desktop subgrid block of the query settings panel, keyed by selector. */
function querySettingsSubgridRules(css) {
    const block = css.match(/@media \(min-width: 641px\) \{\s*@supports \(grid-template-rows: subgrid\) \{([\s\S]*?)\n\t\}\n\}/);
    assert.ok(block, 'Expected the query settings subgrid block');
    const rules = {};
    const rule = /((?:[^{}]|\n)+?)\{([^}]*)\}/g;
    let match;
    while ((match = rule.exec(block[1])) !== null) {
        rules[match[1].replace(/\s+/g, ' ').trim()] = match[2];
    }
    return rules;
}

test('the forced strategy field is a label/control/help field like Timeout', () => {
    const markup = queryPageMarkup();
    assert.match(markup, /id="lmdb-forced-strategy-field" class="workbench-disclosure__field lmdb-forced-strategy-field"/);
});

test('the forced strategy field shares the Timeout subgrid rows so labels, controls and help lines align', () => {
    const rules = querySettingsSubgridRules(fs.readFileSync(stylesheet, 'utf8'));
    const spanning = Object.keys(rules).filter(selector => /grid-row:\s*1 \/ span 3/.test(rules[selector]));
    assert.equal(spanning.length, 1, 'one rule spans the three rows');
    assert.match(spanning[0], /\.query-timeout-field/);
    assert.match(spanning[0], /\.lmdb-forced-strategy-field/);
    assert.match(rules[spanning[0]], /grid-template-rows:\s*subgrid/);
    const middleRow = Object.keys(rules).filter(selector => /grid-row:\s*2;/.test(rules[selector]));
    assert.equal(middleRow.length, 1, 'one rule places the remaining items on the control row');
    assert.match(middleRow[0], /:not\(\.query-timeout-field\)/);
    assert.match(middleRow[0], /:not\(\.lmdb-forced-strategy-field\)/);
    const helpSelectors = Object.keys(rules).filter(selector => /workbench-field__help/.test(selector));
    assert.ok(helpSelectors.some(selector => /\.lmdb-forced-strategy-field/.test(selector)),
        'the strategy help line keeps the field gap below its control');
});
